node -e "
const chunks = [];
process.stdin.on('data', d => chunks.push(d));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(Buffer.concat(chunks).toString());
    const prompt = (input.userPrompt || '').toLowerCase();

    const phases = [
      {
        category: 'DEBUGGING',
        agent: 'Debugging Agent',
        model: 'Claude Sonnet 4',
        keywords: ['failure','failing test','failing tests','investigate','debug','root cause','error analysis','fix failure','exception','stack trace','crash','not working','broken','error log','unexpected behavior','why is this failing','connection refused','timeout error','regression']
      },
      {
        category: 'CODE_REVIEW',
        agent: 'Code Review Agent',
        model: 'Claude Sonnet 4.5',
        keywords: ['code review','review implementation','review code','review this','architecture review','security review','security audit','performance review','performance audit','audit','test coverage review','check this code','does this follow standards','analyze this implementation']
      },
      {
        category: 'TESTING',
        agent: 'QA Agent',
        model: 'Claude Haiku 4.5',
        keywords: ['test cases','testing','qa','validation','regression','automation','unit test','integration test','write tests','generate tests','test coverage','test data','test scenario','api testing','end-to-end','e2e test','test suite','test plan','boundary test','negative test']
      },
      {
        category: 'DEVELOPMENT',
        agent: 'Development Agent',
        model: 'Claude Sonnet 4',
        keywords: ['implement','develop','code','create feature','modify functionality','refactor','build','write code','add endpoint','update logic','add route','add controller','add service','create migration','apply fix','integrate','scaffold','connect api','set up component']
      },
      {
        category: 'DOCUMENTATION',
        agent: 'Documentation Agent',
        model: 'MiniMax M2.1',
        keywords: ['documentation','readme','api documentation','release notes','developer guide','update docs','write docs','document this','technical writing','changelog','usage guide','onboarding','runbook','wiki']
      },
      {
        category: 'DESIGN',
        agent: 'Design Agent',
        model: 'Claude Sonnet 4.5',
        keywords: ['architecture','system design','technical design','api design','database design','solution design','schema design','data model','component design','sequence diagram','high-level design','low-level design','design pattern','design document','design spec']
      },
      {
        category: 'REQUIREMENT',
        agent: 'Design Agent',
        model: 'Claude Sonnet 4.5',
        keywords: ['requirement','business requirement','acceptance criteria','analyze requirement','clarify requirement','functional requirement','non-functional','user story','use case','scope','inception','discovery','gap analysis','product requirement','what should the system','what does the user need']
      }
    ];

    let detected = null;
    for (const p of phases) {
      if (p.keywords.some(k => prompt.includes(k))) {
        detected = p;
        break;
      }
    }

    if (detected) {
      process.stdout.write(
        '[Phase Observer] Routing Category: ' + detected.category +
        ' | Agent: ' + detected.agent +
        ' | Model: ' + detected.model + '\n' +
        'Tip: Use @Northstar Router for automatic phase detection and model selection.\n'
      );
    }
    process.exit(0);
  } catch(e) {
    process.exit(0);
  }
});
"
